SELECT *
FROM shopwizard.tCmpComp

    AND SvcCode = #{pSvcCode}
    AND CompCode = #{pCompCode}
    AND CompName LIKE CONCAT('%',#{pCompName},'%')
    AND State = #{pState}

ORDER BY ${sidx} ${sord}
LIMIT ${pPageOffset}, ${pPageSize}

SELECT COUNT(*)
FROM shopwizard.tCmpComp

    AND SvcCode = #{pSvcCode}
    AND CompCode = #{pCompCode}
    AND CompName LIKE CONCAT('%',#{pCompName},'%')
    AND State = #{pState}
